    var i := 0;
    while i < file_name.Length
        invariant 0 <= i <= file_name.Length
        invariant dotCount == CountDots(file_name.Substring(0, i))
    {
        if file_name[i] == '.' {
            dotCount := dotCount + 1;
        }
        i := i + 1;
    }
