function SubstringBeforeDotIsValid(file_name: string): bool
    reads {}
{
    var dotIndex := file_name.IndexOf('.');
    if dotIndex <= 0 {
        return false;
    }
    var firstChar := file_name[0];
    return (firstChar >= 'a' && firstChar <= 'z') || (firstChar >= 'A' && firstChar <= 'Z');
}

function SubstringAfterDotIsValid(file_name: string): bool
    reads {}
{
    var dotIndex := file_name.IndexOf('.');
    if dotIndex < 0 || dotIndex == file_name.Length - 1 {
        return false;
    }
    var extension := file_name.Substring(dotIndex + 1);
    return extension == "txt" || extension == "exe" || extension == "dll";
}

